#include <stdint.h>
#include <stdio.h>
#include "led.h"
#include "adc.h"
#include "registers.h"

#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

int main(void)
{
	led_init();
	adc_init();

	adc_start();

	while(1)
	{

		if(adc_value <= 1366)
		{
			led_on(LED1);
			led_off(LED2);
			led_off(LED3);
		}
		else if(adc_value <= 2732)
		{
			led_on(LED2);
			led_off(LED1);
			led_off(LED3);
		}
		else
		{
			led_on(LED3);
			led_off(LED1);
			led_off(LED2);
		}
	}

}
